let session={authenticated:false},state=F.demoState(),revision=0,dirty=false,syncError='',saveVersion=0,saving=false,saveTimer,saveStatus='이 브라우저에 저장',modalType='',lastFocus,toastTimer;
let month=F.monthOf(F.today()),page='dashboard',flowView='accounts',entryQuery='',entryType='all',entryStatus='all',entryPage=0,subscriptionFilter='active',shareIncludeAssets=false,shareDays=7,shareRows=[],shared=null,sharedError='',shareToken=new URLSearchParams(location.search).get('share'),memoryLinks={};
let flowAccountId=null,riverExpanded='group:fixed',riverScene=null,motionPaused=false;
let localStorageAvailable=true,accountChanged=false,browserLedger={status:'missing'};const cloudKey=()=>`moaflow:account:${session.user?.key||'unknown'}:v1`;
const storageKey=()=>state.sample?DEMO_KEY:session.authenticated?cloudKey():REAL_KEY;
const read=(key)=>{try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}};
const inspectBrowserLedger=()=>{let raw=null;try{raw=localStorage.getItem(REAL_KEY);}catch{}return browserLedger=F.readStoredLedger(raw);};
const account=id=>state.accounts.find(a=>a.id===id),category=id=>state.categories.find(c=>c.id===id),accountName=id=>account(id)?.name||'계좌',categoryName=id=>category(id)?.name||'미분류';
const money=n=>state.settings.hideAmounts?'••••':F.won(n),amount=n=>state.settings.hideAmounts?'••••':Math.round(n).toLocaleString('ko-KR');
const visibleAmount=n=>`${amount(n)}${state.settings.hideAmounts?'':'<span class="unit">원</span>'}`;
const koreanDate=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d));
const dateShort=d=>`${Number(d.slice(5,7))}.${Number(d.slice(8,10))}`;
const dateLabel=d=>`${Number(d.slice(5,7))}월 ${Number(d.slice(8,10))}일`;
const empty=(title,body)=>`<div class="empty"><h3>${title}</h3><p>${body}</p></div>`;
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
const api=createAccountApi({getAccountKey:()=>session.authenticated?session.user?.key:null,onAccountChanged:()=>{
 accountChanged=true;clearTimeout(saveTimer);saveStatus='계정 확인 필요';syncError='다른 계정으로 로그인한 것이 확인되어 저장을 멈췄어요.';persist();closeModal();render();
}});
function changedAccountView(){return `<section class="panel section-body account-lock"><h1>로그인한 계정이 바뀌었어요</h1><p>열어 둔 가계부를 다른 계정에 저장하지 않도록 멈췄어요. ${localStorageAvailable?'전송하지 못한 기록은 이전 계정의 자료로 이 브라우저에 보관했어요.':'브라우저에 보관하지 못한 기록이 있어요. 먼저 전체 백업을 저장해 주세요.'}</p><p>현재 계정으로 다시 열거나, 이전 계정으로 로그인한 뒤 남은 기록을 확인할 수 있어요.</p><div class="settings-buttons"><button class="btn" data-action="export-backup">전체 백업 저장</button><button class="btn primary" data-action="reload-session">현재 계정으로 다시 열기</button></div></section>`;}

function persist(){if(storageKey()===REAL_KEY&&browserLedger.status==='invalid'){saveStatus='저장 보류 · 이전 가계부 확인 필요';askBrowserRecovery();return false;}try{localStorage.setItem(storageKey(),JSON.stringify({state,revision,dirty}));localStorageAvailable=true;return true;}catch{localStorageAvailable=false;saveStatus='브라우저 저장 안 됨';toast('브라우저 저장 공간이 부족해요. 전체 백업을 내려받아 주세요.');return false;}}
function askBrowserRecovery(){modalType='confirm';showModal('이전 가계부를 읽을 수 없어요','원본은 바꾸지 않았어요. 어떻게 할지 선택해 주세요.',`<p class="subtle">이 브라우저에 저장된 가계부를 열 수 없어요(${esc(browserLedger.reason||'형식 확인 필요')}). 원본을 그대로 내려받아 보관하거나, 원본을 이 브라우저의 별도 공간에 보관한 뒤 새 가계부를 시작할 수 있어요. 지금 화면의 예시나 새 기록을 내보내는 전체 백업은 이 원본의 백업이 아니에요.</p><div class="form-actions"><button class="btn" data-action="download-browser-original">원본 그대로 내려받기</button></div><div class="form-actions"><button class="btn" data-action="close-modal">취소</button><button class="btn danger" data-action="confirm-keep-browser-original">원본 보관 후 새로 시작</button></div>`);}
function commit(message='저장했어요.'){
 try{F.validateState(state);}catch(error){toast(error.message);return false;}
 state.updatedAt=new Date().toISOString();saveVersion++;dirty=!state.sample&&session.authenticated;const saved=persist();
 if(dirty){saveStatus='계정에 저장 중';clearTimeout(saveTimer);saveTimer=setTimeout(saveCloud,300);}else saveStatus=state.sample?'예시로 체험 중':'이 브라우저에 저장';
 render();if(message&&saved)toast(message);return true;
}
async function saveCloud(){
 if(saving||!dirty||state.sample||!session.authenticated||syncError||accountChanged)return;
 saving=true;const version=saveVersion,snapshot=structuredClone(state),expected=revision;
 try{const response=await api('state',{method:'PUT',body:{revision:expected,state:snapshot}});revision=response.revision;dirty=version!==saveVersion;saveStatus=dirty?'계정에 저장 중':'계정에 저장됨';persist();}
 catch(error){if(accountChanged)return;syncError=error.status===409?'다른 기기에서 저장한 자료와 버전이 달라요. 입력한 내용은 이 기기에 남아 있어요.':'계정에 저장하지 못했어요. 입력한 내용은 이 기기에 남아 있어요.';saveStatus='기기 저장 · 동기화 필요';persist();}
 finally{saving=false;updateSaveStatus();if(dirty&&!syncError)setTimeout(saveCloud,200);if(syncError)render();}
}
function updateSaveStatus(){const el=$('#save-status');if(el){el.innerHTML=`<i class="dot"></i>${esc(saveStatus)}`;el.classList.toggle('error',!!syncError||!localStorageAvailable);}}
function monthPicker(){return`<div class="month-picker"><button data-action="month-prev" aria-label="이전 달">${I('chevron','left-chevron')}</button><input type="month" value="${month}" id="month-picker" min="2000-01" max="2100-12" aria-label="조회할 월"><button data-action="month-next" aria-label="다음 달">${I('chevron')}</button></div>`;}
function heading(eyebrow,title,subtitle,button=''){return`<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="page-controls">${monthPicker()}${button}</div></div>`;}
function render(){
 const previousRiverScroll=$('.river-scroll')?.scrollLeft;
 const hash=location.hash.slice(1);page=Object.hasOwn(paths,hash)?hash:'dashboard';
 const pending=F.reminders(state).length;
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="logo" href="${ledgerBrand.home}"><img src="/moaflow/mark.svg" alt=""><span><strong>${ledgerBrand.label}</strong><small>나의 작은 재무제표</small></span></a><button class="book-selector" data-action="open-settings">${I('ledger')}<strong>${esc(shareToken?'친구의 비중 자료':state.book.name)}</strong>${I('chevron')}</button><p class="nav-caption">MY FINANCIAL STORY</p><nav class="nav" aria-label="주 메뉴">${Object.entries(paths).map(([id,label])=>`<a href="#${id}" data-page="${id}" class="${page===id&&!shareToken?'active':''}" ${page===id&&!shareToken?'aria-current="page"':''}>${I(id)}<span>${label}</span>${id==='sharing'?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="side-note">${I('leaf')}<strong>잘 쌓인 기록은<br>더 나은 선택이 됩니다.</strong><p>오늘의 작은 흐름부터.</p></div><div class="side-bottom"><a href="${ledgerBrand.parent}" target="_top">${ledgerBrand.parentLabel} ${I('arrow')}</a><p>MAKE ROOM FOR TOMORROW.</p></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb">나의 공간 <span>/</span> <strong>${shareToken?'친구의 비중 자료':paths[page]}</strong></div><a href="${ledgerBrand.home}" class="mobile-brand"><img src="/moaflow/mark.svg" alt=""><strong>${ledgerBrand.label}</strong></a><div class="top-tools"><span id="save-status" class="storage-status ${syncError?'error':''}"><i class="dot"></i>${esc(shareToken?'공유 비중 자료 보기':saveStatus)}</span><button class="tool-btn" data-action="search" aria-label="거래와 계좌 검색">${I('search')}</button><button class="tool-btn" data-action="toggle-amounts" aria-label="${state.settings.hideAmounts?'금액 표시':'금액 숨기기'}">${I('eye')}</button><button class="tool-btn" data-action="notifications" aria-label="구독 알림">${I('bell')}${pending?'<i class="notice-dot"></i>':''}</button><button class="profile-btn" data-action="open-settings" aria-label="계정과 설정"><span class="avatar">${session.authenticated?'M':'m'}</span><span>${esc(session.user?.name||'나의 공간')}</span>${I('chevron')}</button></div></header><main class="main" id="main-content" tabindex="-1">${syncError&&!state.sample&&!accountChanged?`<div class="sync-strip"><span>${esc(syncError)}</span><div><button class="btn small" data-action="export-backup">전체 백업</button> <button class="btn small" data-action="reload-cloud">최신 자료 불러오기</button></div></div>`:''}<div class="page-view">${accountChanged?changedAccountView():shareToken?sharedView():({dashboard:dashboardView,ledger:ledgerView,subscriptions:subscriptionsView,assets:assetsView,statements:statementsView,sharing:sharingView,settings:settingsView})[page]()}</div><footer class="footer"><span><i class="dot"></i> ${ledgerBrand.label} · ${shareToken?'공유 비중 자료 · 금액 비공개':state.sample?'예시로 둘러보는 중':session.authenticated?'나의 계정에 차곡차곡':'이 기기에 차곡차곡'}</span><span><a href="#settings">저장·알림 설정</a> · <a href="${ledgerBrand.parent}" target="_top">${ledgerBrand.parentLabel}</a></span></footer></main></div></div>`;
 syncRiverMotion(document,motionPaused);const scroller=$('.river-scroll');if(scroller)scroller.scrollLeft=previousRiverScroll??(matchMedia('(max-width:700px)').matches?350:0);
}
function demoStrip(){return state.sample?`<div class="demo-strip"><span class="inline">${I('info')}<span><strong>예시 데이터</strong> · 실제 내역이 아닌 체험용 가계부예요.</span></span><button data-action="start-real">${session.authenticated?'내 가계부로 돌아가기':'내 가계부 시작하기'} →</button></div>`:'';}
function metric(color,icon,label,value,foot,action,id=''){return`<button class="metric ${color}" data-action="${action}" data-id="${esc(id)}"><div class="metric-top"><span class="metric-label">${label}</span>${tile(icon,color)}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></button>`;}
function fourMetrics(m){return`<section class="metrics" aria-label="이번 달 재무 요약">${metric('blue','income','이번 달 수입',visibleAmount(m.income),'내게 들어온 모든 수입','kind-detail','income')}${metric('orange','expense','이번 달 지출',visibleAmount(m.expense),'정기 지출 + 일상 지출','kind-detail','expense')}${metric('green','wallet','이번 달 남은 돈',visibleAmount(m.net),m.income?`수입 중 ${m.savingsRate}%를 남겼어요`:'수입을 기록하면 비중이 보여요','retained')}${metric('purple','assets','나의 순자산',visibleAmount(m.netAssets),`총자산 − 부채 · ${month===F.monthOf(F.today())?'현재 기준':'월말 기준'}`,'open-assets')}</section>`;}
function dashboardView(){const m=F.monthly(state,month),scheduled=F.subscriptionEvents(state,F.today(),F.addDays(F.today(),30)).filter(s=>!s.paid).slice(0,4),past=Array.from({length:6},(_,i)=>{const date=F.shiftMonth(month,i-5);return{month:date,...F.monthly(state,date)};});return`${heading('MY MONEY RIVER','내 돈의 흐름','수입부터 계좌 이동과 지출까지, 한눈에 살펴보세요.',`<button class="btn primary" data-action="new-entry">${I('plus')} 거래 기록하기</button>`)}${demoStrip()}${moneyFlowPanel(m)}<div class="river-after-metrics">${fourMetrics(m)}</div><div class="dashboard-bottom"><section class="panel"><div class="panel-header"><h2>다가오는 구독 결제</h2><button class="text-btn" data-action="open-subscriptions">전체 보기 ${I('chevron')}</button></div><div style="padding-top:13px">${scheduled.map(subRow).join('')||empty('예정된 결제가 없어요','구독을 추가하면 결제일을 챙겨드려요.')}</div></section><section class="panel"><div class="panel-header"><h2>수입과 지출의 발자취</h2><span class="kicker">최근 6개월</span></div><div class="section-body">${bars(past,state.settings.hideAmounts)}<div class="bar-legend"><span><i></i>수입</span><span><i></i>지출</span></div></div></section><section class="panel insight-panel"><div class="panel-header"><h2>작은 재무 노트</h2>${I('leaf')}</div><div class="section-body"><p class="insight-hero">${m.net>0?`이번 달은<br><em>${money(m.net)}</em>만큼<br>내일을 위한 여유가 생겼어요.`:m.net<0?'이번 달 지출이<br>수입보다 많았어요.<br><em>흐름부터 천천히 살펴봐요.</em>':'처음의 기록이 모여<br>나만의 재무 이야기가<br><em>시작됩니다.</em>'}</p><div class="insight-rule"></div><p class="insight-foot">${state.settings.monthlyBudget?`지출 목표 ${money(state.settings.monthlyBudget)} 중<br>${money(m.expense)}을 사용했어요.`:'나에게 맞는 월 지출 목표를 설정해 보세요.'}<br><button class="text-btn" data-action="open-statements">내 재무제표 펼쳐보기 →</button></p></div></section></div>`;}
function moneyFlowPanel(m){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,animated=flowView==='accounts'&&!motionPaused&&!reduced;
 let content='';
 if(flowView==='accounts'){
  const graph=graphFromLedger(state,month);if(!state.accounts.some(a=>a.id===flowAccountId))flowAccountId=preferredFlowAccount(graph);
  riverScene=buildRiverScene(graph,flowAccountId,riverExpanded);const scene=riverScene;
  content=`<div class="river-toolbar"><label class="river-selector"><span>중심 계좌</span><select id="river-account" aria-label="흐름의 중심 계좌">${state.accounts.map(a=>`<option value="${esc(a.id)}" ${a.id===flowAccountId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><div class="river-total-strip"><span>들어온 기록 <strong>${money(scene.incomingTotal)}</strong></span><span>나간 기록 <strong>${money(scene.outgoingTotal)}</strong></span></div><button class="river-motion" data-action="river-motion" aria-pressed="${motionPaused}" ${reduced?'disabled title="기기의 동작 줄이기 설정을 따르고 있어요."':''}>${I(motionPaused?'play':'pause')}<span>${reduced?'동작 줄이기 적용':motionPaused?'움직임 재생':'움직임 멈추기'}</span></button></div><div class="river-legend"><span><i style="background:#7d9acb"></i>수입</span><span><i style="background:#9b7bd4"></i>계좌 이동</span><span><i style="background:#c58da8"></i>지출·카드 사용</span><span><i style="background:#d6a080"></i>상환</span><span class="river-tip">노드를 누르면 상세 · 작은 화살표는 가지 펼치기</span></div><p class="river-swipe-hint">← 좌우로 밀어 전체 흐름을 살펴보세요 →</p>${renderRiver(scene,{hide:state.settings.hideAmounts,paused:motionPaused,reduced})}<div class="river-inspector">${I('flow')}<span id="river-inspector">입자가 움직이는 길을 따라가 보세요. 계좌와 연결선을 누르면 기록을 수정할 수 있어요.</span></div>${!scene.hasRecords?`<div class="river-empty"><h3>첫 기록을 남기면 물길이 열려요.</h3><p>수입, 계좌 이체나 지출을 기록하면 이 지도에 연결돼요.</p><button class="btn primary" data-action="river-first-income">수입부터 기록하기</button> <button class="btn" data-action="new-entry">지출 기록하기</button></div>`:''}<div class="river-explainer"><span>수기로 기록한 이번 달 확정 거래예요. <strong>계좌 이체·상환은 지출에 다시 더하지 않아요.</strong></span><span>${scene.secondary?'카드 사용과 대금 상환은 각각의 기록으로 표시해요.':'중심 계좌를 바꾸면 다른 계좌의 물길도 볼 수 있어요.'}</span></div>`;
 }else content=`<div class="flow-info"><span><i></i>수입</span><span><i></i>정기 지출</span><span><i></i>일상 지출</span><span><i></i>남은 돈</span></div>${flowView==='flow'?sankey(state,m,state.settings.hideAmounts):flowSummary(m)}<div class="graph-foot">${I('info')} 항목을 누르면 연결된 거래를 확인하고 수정할 수 있어요.</div>`;
 return`<section class="panel flow-panel river-panel" aria-label="계좌와 지출의 돈 흐름 지도"><div class="panel-header"><div><div class="river-title-row"><h2>돈이 흐르는 지도</h2>${flowView==='accounts'?`<span class="river-live ${animated?'running':''}"><i></i>${motionPaused||reduced?'STILL':'LIVE FLOW'}</span>`:''}</div><p>들어온 돈이 어느 계좌를 지나, 어디로 향했는지.</p></div><div class="panel-header-tools"><div class="segmented" role="group" aria-label="돈의 흐름 보기"><button data-action="flow-view" data-id="accounts" class="${flowView==='accounts'?'active':''}" aria-pressed="${flowView==='accounts'}">계좌 흐름</button><button data-action="flow-view" data-id="flow" class="${flowView==='flow'?'active':''}" aria-pressed="${flowView==='flow'}">수입·지출</button><button data-action="flow-view" data-id="summary" class="${flowView==='summary'?'active':''}" aria-pressed="${flowView==='summary'}">요약표</button></div></div></div>${content}</section>`;
}
function riverItem(key){return riverScene?.nodes.find(n=>n.key===key)||riverScene?.connections.find(n=>n.key===key);}
function openRiverDetails(key){
 const item=riverItem(key);if(!item)return;if(item.hub){openAccount(flowAccountId);return;}
 const entries=state.entries.filter(e=>item.entryIds.includes(e.id)).sort((a,b)=>b.date.localeCompare(a.date)||b.order-a.order);
 const accountNode=item.entityKind==='account',kind=accountNode?(item.accountType==='liability'?'부채 계좌':'자산 계좌'):item.entityKind==='group'?'지출 분류':item.entityKind==='income'?'수입 분류':item.entityKind==='expense'?'지출 분류':'연결된 거래';
 modalType='river-details';showModal(item.label,`${month} · ${kind}`,`<div class="river-detail-route"><span>${esc(item.routeFrom||item.source?.label||riverScene.focus.label)}</span> → <span>${esc(item.routeTo||item.target?.label||item.label)}</span></div><div class="modal-amount"><small>이 흐름의 ${entries.length}개 기록</small>${money(item.amount)}</div>${accountNode?`<div class="settings-buttons" style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-action="account" data-id="${esc(item.entityId)}">계좌 정보 수정</button><button class="btn green" data-action="river-focus" data-id="${esc(item.entityId)}">이 계좌의 흐름 보기 →</button></div>`:''}<div class="river-detail-note">${item.kind==='repayment'?'카드·대출 상환은 부채를 갚는 거래예요. 지출로 중복 계산하지 않아요.':item.kind==='transfer'?'계좌 사이에서 이동한 금액이에요. 소비 지출로 계산하지 않아요.':item.accountType==='liability'||entries.some(e=>e.kind==='expense'&&account(e.from)?.group==='card')?'카드 사용과 카드대금 상환은 구분해서 기록해요. 아래 기록을 누르면 실제 결제 내용을 수정할 수 있어요.':'금액과 날짜를 수정하면 계좌 잔액과 이 흐름도도 함께 다시 계산돼요.'}</div>${entries.map(detailEntry).join('')||empty('이달의 연결 기록이 없어요','기록을 추가하면 물길이 생겨요.')}<div class="form-actions"><button class="btn" data-action="close-modal">닫기</button><button class="btn primary" data-action="river-add" data-id="${esc(key)}">이 흐름에 새 기록</button></div>`,true);
}
function addRiverEntry(key){const item=riverItem(key),first=state.entries.find(e=>item?.entryIds.includes(e.id));if(!first){openEntry(null,{from:flowAccountId});return;}const defaults={kind:first.kind,description:'',amount:''};for(const field of ['from','to','categoryId','accountId'])if(first[field])defaults[field]=first[field];openEntry(null,defaults);}

function flowSummary(m){const items=[...Object.entries(m.incomeByCategory).map(([id,value])=>({id,value,type:'income'})),...Object.entries(m.expenseByCategory).map(([id,value])=>({id,value,type:'expense'}))];return`<div class="summary-list">${items.map(r=>`<button data-action="category" data-id="${esc(r.id)}">${tile(r.type,category(r.id)?.color||'blue')}<span>${esc(categoryName(r.id))}</span><small>${r.type==='income'?'수입':category(r.id)?.group==='fixed'?'정기':'일상'}</small><strong>${money(r.value)}</strong></button>`).join('')||empty('아직 기록이 없어요','수입이나 지출을 남겨보세요.')}<button data-action="retained"><span class="bullet green"></span><span>남은 돈</span><strong>${money(m.net)}</strong></button></div>`;}
function subRow(s){return`<button class="subscription-row" data-action="subscription" data-id="${esc(s.id)}"><span class="service-icon ${s.color}">${esc(s.name.slice(0,1))}</span><span class="row-main"><strong>${esc(s.name)}</strong><small>${dateLabel(s.date)} 결제 예정</small></span><span class="row-amount">${money(s.amount)}<small>${s.cadence==='monthly'?'월간 구독':'연간 구독'}</small></span></button>`;}
function filteredEntries(){const q=entryQuery.toLowerCase().trim();return state.entries.filter(e=>F.monthOf(e.date)===month&&(entryType==='all'||e.kind===entryType)&&(entryStatus==='all'||e.status===entryStatus)&&(!q||(e.description+' '+(e.memo||'')+' '+accountName(e.from||e.to||e.accountId)+' '+categoryName(e.categoryId)).toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date)||b.order-a.order);}
function entryRoute(e){return e.kind==='income'?`${categoryName(e.categoryId)} → ${accountName(e.to)}`:e.kind==='expense'?`${accountName(e.from)} · ${categoryName(e.categoryId)}`:e.kind==='valuation'?`${accountName(e.accountId)} 평가액 갱신`:`${accountName(e.from)} → ${accountName(e.to)}`;}
function ledgerTable(){const list=filteredEntries(),start=entryPage*20,shown=list.slice(start,start+20);return`<div class="table-scroll"><table class="table"><thead><tr><th>날짜</th><th>기록한 내용</th><th>구분</th><th>상태</th><th class="numeric">금액</th><th><span class="sr-only">관리</span></th></tr></thead><tbody>${shown.map(e=>`<tr><td>${dateShort(e.date)}</td><td><button data-action="entry" data-id="${esc(e.id)}" class="entry-description">${esc(e.description)}</button><small>${esc(entryRoute(e))}</small></td><td>${F.KIND_LABELS[e.kind]}</td><td><span class="tag ${e.status==='posted'?'green':'blue'}">${e.status==='posted'?'기록 완료':'예정'}</span></td><td class="numeric"><span class="amount ${e.kind==='income'?'income':e.kind==='expense'?'expense':''}">${e.kind==='income'?'+':''}${money(e.kind==='valuation'?e.targetBalance:e.amount)}</span></td><td><div class="row-actions"><button data-action="entry" data-id="${esc(e.id)}" aria-label="${esc(e.description)} 수정">${I('edit')}</button><button data-action="delete-entry" data-id="${esc(e.id)}" aria-label="${esc(e.description)} 삭제">${I('trash')}</button></div></td></tr>`).join('')}</tbody></table>${shown.length?'':empty('이 달에는 아직 기록이 없어요','다른 달을 선택하거나 첫 거래를 남겨보세요.')}</div><div class="table-bottom"><span>총 ${list.length}개 기록 · ${Math.min(start+1,list.length)}–${Math.min(start+20,list.length)}</span><div class="pagination"><button data-action="entries-prev" ${entryPage===0?'disabled':''}>이전</button><button data-action="entries-next" ${(start+20)>=list.length?'disabled':''}>다음</button></div></div>`;}
function ledgerView(){const m=F.monthly(state,month);return`${heading('MY DAILY RECORDS','하루를 담은 거래 기록','수입도, 지출도, 계좌 사이의 이동도 한곳에.',`<button class="btn primary" data-action="new-entry">${I('plus')} 거래 기록하기</button>`)}${demoStrip()}${fourMetrics(m)}<div class="toolbar"><div class="filters"><div class="search-field">${I('search')}<input class="input" id="ledger-search" type="search" value="${esc(entryQuery)}" placeholder="내용, 계좌, 분류로 찾기" aria-label="거래 검색"></div><select class="input small" id="entry-kind-filter" aria-label="거래 종류 필터"><option value="all">모든 거래</option>${Object.entries(F.KIND_LABELS).map(([id,label])=>`<option value="${id}" ${entryType===id?'selected':''}>${label}</option>`).join('')}</select><select class="input small" id="entry-status-filter" aria-label="거래 상태 필터"><option value="all">모든 상태</option><option value="posted" ${entryStatus==='posted'?'selected':''}>기록 완료</option><option value="planned" ${entryStatus==='planned'?'selected':''}>예정</option></select></div><button class="text-btn" data-action="export-csv">${I('download')} 이 달의 거래 CSV</button></div><section class="panel" id="ledger-table-region">${ledgerTable()}</section><div class="info-note">${I('info')} 카드 사용은 지출과 카드 부채로, 카드대금 납부는 상환으로 기록해요. 이체·투자금 이동·상환은 지출에 다시 더하지 않아요. 예정 거래는 재무제표 합계에서 제외해요.</div>`;}
function subscriptionsView(){const active=state.subscriptions.filter(s=>s.active),equiv=active.reduce((n,s)=>n+s.amount/(s.cadence==='yearly'?12:1),0),due=F.subscriptionEvents(state,month+'-01',F.monthEnd(month)),unpaid=due.filter(s=>!s.paid),filtered=state.subscriptions.filter(s=>subscriptionFilter==='all'||(subscriptionFilter==='active'?s.active:!s.active));return`${heading('LESS TO REMEMBER','구독은 가볍게, 결제는 놓치지 않게','매달 나가는 작은 금액도 모이면 큰 흐름이 돼요.',`<button class="btn primary" data-action="new-subscription">${I('plus')} 구독 추가</button>`)}${demoStrip()}<section class="metrics">${metric('orange','subscriptions','월 환산 구독료',visibleAmount(Math.round(equiv)),'연간 구독은 12개월로 나눠 계산','all-subscriptions')}${metric('blue','calendar','이달 구독 결제액',visibleAmount(due.reduce((n,s)=>n+s.amount,0)),`${due.length}건의 결제 일정`,'month-subscriptions')}${metric('green','check','기록 완료',`${state.entries.filter(e=>e.subscriptionId&&e.status==='posted'&&F.monthOf(e.date)===month).length}<span class="unit">건</span>`,'결제 완료로 기록한 내역','all-subscriptions')}${metric('purple','bell','아직 확인할 결제',`${unpaid.length}<span class="unit">건</span>`,'예정 또는 지난 결제 확인','notifications')}</section><div class="toolbar"><div class="segmented" role="group" aria-label="구독 필터">${[['active','사용 중'],['paused','일시정지'],['all','전체']].map(([id,label])=>`<button data-action="subscription-filter" data-id="${id}" class="${subscriptionFilter===id?'active':''}">${label}</button>`).join('')}</div><button class="text-btn" data-action="calendar-export">${I('calendar')} 결제일을 캘린더로</button></div><div class="card-grid">${filtered.map(s=>{const next=F.subscriptionEvents(state,F.today(),F.addDays(F.today(),370)).find(x=>x.id===s.id&&!x.paid),current=due.find(x=>x.id===s.id);return`<article class="subscription-card ${s.active?'':'paused'}"><div class="card-top"><span class="service-icon ${s.color}">${esc(s.name.slice(0,1))}</span><div class="row-main"><strong>${esc(s.name)}</strong><small>${s.cadence==='yearly'?'연간 구독':'월간 구독'}</small></div><div class="card-tools"><button class="switch" role="switch" aria-checked="${s.active}" data-action="toggle-subscription" data-id="${esc(s.id)}" aria-label="${esc(s.name)} 사용"></button><button class="tool-btn" data-action="subscription" data-id="${esc(s.id)}" aria-label="${esc(s.name)} 구독 수정">${I('edit')}</button></div></div><div class="card-price">${money(s.amount)}<small>/ ${s.cadence==='yearly'?'년':'월'}</small></div><p class="subtle">${esc(accountName(s.accountId))} · ${esc(categoryName(s.categoryId))}</p><div class="card-meta"><span>${current?.paid?'이달 결제 기록 완료':next?`다음 결제 ${dateLabel(next.date)}`:s.active?'결제일 확인':'현재 일시정지'}</span>${current&&!current.paid&&current.date<=F.today()?`<button class="btn small green" data-action="charge-subscription" data-id="${esc(s.id)}" data-date="${current.date}">결제 기록</button>`:`<button class="text-btn" data-action="subscription" data-id="${esc(s.id)}">상세 ${I('chevron')}</button>`}</div></article>`;}).join('')||empty('아직 구독이 없어요','결제일과 금액을 등록하면 함께 챙겨드릴게요.')}</div><div class="info-note">${I('info')} 구독을 등록해도 실제 지출에 자동으로 더하지 않아요. 결제된 날 ‘결제 기록’을 누르면 가계부에 한 번만 반영돼요. 월말 결제일은 그 달의 마지막 날을 기준으로 계산해요.</div>`;}
function assetsView(){const m=F.monthly(state,month),history=F.assetHistory(state,month),gain=history.at(-1).netAssets-history[0].netAssets;return`${heading('GROW AT YOUR PACE','내 자산의 발자취','지금의 숫자를 기록하고, 변화의 방향을 살펴보세요.',`<button class="btn primary" data-action="new-valuation">${I('plus')} 자산가치 기록</button>`)}${demoStrip()}<section class="metrics">${metric('blue','wallet','총자산',visibleAmount(m.assets),'내가 보유한 자산 합계','asset-group','asset')}${metric('orange','subscriptions','남은 부채',visibleAmount(m.liabilities),'카드 미결제액과 대출','asset-group','liability')}${metric('green','assets','순자산',visibleAmount(m.netAssets),'총자산에서 부채를 뺀 금액','open-statements')}${metric('purple','income','최근 6개월 순자산 변화',visibleAmount(gain),'기록된 평가액과 거래 반영','history-point',history.at(-1).date)}</section><div class="asset-layout"><section class="panel"><div class="panel-header"><div><h2>차곡차곡 쌓인 자산</h2><p>최근 6개월 · 월말 기준, 이번 달은 현재 기준</p></div><span class="tag green">수기 기록 반영</span></div><div class="section-body" style="padding:15px 18px 0">${lineChart(history,state.settings.hideAmounts)}</div><div class="trend-legend"><span><i></i>순자산</span><span><i></i>총자산</span></div></section><section class="panel"><div class="panel-header"><h2>자산의 균형</h2><button class="text-btn" data-action="new-account">계좌 추가 ${I('plus')}</button></div><div class="section-body">${allocation(state,m.balances,state.settings.hideAmounts)}</div></section></div><div class="account-grid">${state.accounts.map(a=>`<button class="account-card ${a.color}" data-action="account" data-id="${esc(a.id)}"><div class="card-top">${tile(a.type==='liability'?'subscriptions':a.group==='investment'?'assets':a.group==='savings'?'leaf':'bank',a.color)}<span><strong>${esc(a.name)}</strong><small>${F.ASSET_GROUPS[a.group]}</small></span></div><div class="balance">${money(m.balances[a.id])}</div><div class="account-foot"><span>${a.type==='liability'?'갚을 금액':'기록된 평가액'}</span><span>상세·가치 갱신 →</span></div></button>`).join('')}<button class="account-add" data-action="new-account">${I('plus')} 나의 계좌 추가하기</button></div><div class="info-note">${I('info')} 은행·증권 API 없이 직접 기록하는 버전이에요. 투자금 이동은 자산 간 이체로, 평가액 변화는 ‘자산가치 기록’으로 반영해요. 평가손익을 월 수입과 지출에 섞지 않아요.</div>`;}
function statementsView(){const m=F.monthly(state,month),previous=F.monthly(state,F.shiftMonth(month,-1));const entries=(items)=>Object.entries(items).map(([id,n])=>`<button class="statement-row child" data-action="category" data-id="${esc(id)}" style="width:100%"><span>${esc(categoryName(id))}</span><strong>${money(n)}</strong></button>`).join('');return`${heading('YOUR PERSONAL FINANCIALS','나를 위한 작은 재무제표','회사처럼 꼼꼼하게, 가계부처럼 쉽게.',`<button class="btn" data-action="export-csv">${I('download')} 거래 내보내기</button>`)}${demoStrip()}<div class="statement-layout"><section class="panel"><div class="statement-heading"><div><h2>이달의 수입과 지출</h2><small>PERSONAL INCOME STATEMENT</small></div><span>${month}</span></div><div class="statement-row group"><span>들어온 돈 · 수입</span><strong>${money(m.income)}</strong></div>${entries(m.incomeByCategory)}<div class="statement-row group"><span>사용한 돈 · 지출</span><strong>${money(m.expense)}</strong></div>${entries(m.expenseByCategory)}<div class="statement-row total"><span>남은 돈 · 이달의 잉여</span><strong>${money(m.net)}</strong></div><div class="statement-note">${m.income?`수입의 ${m.savingsRate}%가 남았어요.`:'아직 수입 기록이 없어요.'}<br>지출에는 카드 사용액이 포함되고, 카드대금 상환과 계좌 이체는 제외돼요.</div></section><section class="panel"><div class="statement-heading"><div><h2>지금의 자산과 부채</h2><small>PERSONAL BALANCE SHEET</small></div><span>${month===F.monthOf(F.today())?'현재':F.monthEnd(month)}</span></div><div class="statement-row group"><span>보유한 자산</span><strong>${money(m.assets)}</strong></div>${state.accounts.filter(a=>a.type==='asset').map(a=>`<button class="statement-row child" style="width:100%" data-action="account" data-id="${esc(a.id)}"><span>${esc(a.name)}</span><strong>${money(m.balances[a.id])}</strong></button>`).join('')}<div class="statement-row group"><span>갚을 부채</span><strong>${money(m.liabilities)}</strong></div>${state.accounts.filter(a=>a.type==='liability').map(a=>`<button class="statement-row child" style="width:100%" data-action="account" data-id="${esc(a.id)}"><span>${esc(a.name)}</span><strong>${money(m.balances[a.id])}</strong></button>`).join('')}<div class="statement-row total"><span>나의 순자산</span><strong>${money(m.netAssets)}</strong></div><div class="statement-note">보유 자산 − 갚을 부채 = 나의 순자산<br>자산가치 갱신과 실제 수입·지출의 영향을 구분해요.</div></section></div><div class="asset-layout"><section class="panel"><div class="panel-header"><h2>지난달과 비교하면</h2></div><div class="section-body"><div class="statement-row"><span>수입 변화</span><strong>${money(m.income-previous.income)}</strong></div><div class="statement-row"><span>지출 변화</span><strong>${money(m.expense-previous.expense)}</strong></div><div class="statement-row"><span>순자산 변화</span><strong>${money(m.netAssets-previous.netAssets)}</strong></div></div></section><section class="panel"><div class="panel-header"><h2>지출 목표까지</h2><button class="text-btn" data-action="open-settings">목표 수정 ${I('chevron')}</button></div><div class="section-body"><div class="budget-head"><span>월 지출 목표</span><strong>${money(state.settings.monthlyBudget)}</strong></div><div class="progress"><i style="width:${state.settings.monthlyBudget?Math.min(100,m.expense/state.settings.monthlyBudget*100):0}%"></i></div><p class="subtle" style="margin-top:15px">${state.settings.monthlyBudget?`${money(Math.max(0,state.settings.monthlyBudget-m.expense))}의 여유가 남았어요.`:'목표 금액을 먼저 설정해 보세요.'}</p></div></section></div>`;}
function sharePreview(payload){return`<div class="privacy-preview"><span class="privacy-label">${I('shield')} 금액 없이, 흐름만 함께</span><h2>${Number(payload.period.slice(5))}월의 지출 이야기</h2><p class="subtitle">실제 금액 대신 비중으로 보는 나의 생활</p>${payload.flow?`<div class="share-flow-bar"><span style="width:${Math.min(payload.flow.spent,100)}%"></span></div><div class="share-flow-labels"><span>수입 대비 지출 ${payload.flow.spent}%</span><span>남긴 비중 ${payload.flow.retained}%</span></div>`:'<p class="subtle">소비 비중을 함께 살펴봐요.</p>'}${payload.composition.map(r=>`<div class="share-category"><div><span>${esc(r.label)}</span><strong>${r.percent}%</strong></div><div class="progress"><i style="width:${r.percent}%"></i></div></div>`).join('')||'<div class="subtle" style="padding:25px 0">공유할 지출 기록이 아직 없어요.</div>'}${payload.allocation?`<p class="subtle" style="margin-top:24px">자산 종류별 비중</p>${payload.allocation.map(r=>`<div class="share-category"><div><span>${esc(r.label)}</span><strong>${r.percent}%</strong></div><div class="progress"><i style="width:${r.percent}%"></i></div></div>`).join('')}`:''}<div class="privacy-foot">공개되는 내용: 넓은 지출 분류와 비중${payload.allocation?', 자산 종류별 비중':''}<br>실제 금액 · 총자산 · 계좌명 · 거래내역은 포함하지 않았어요.</div></div>`;}
function sharingView(){const payload=F.safeShare(state,month,shareIncludeAssets);return`${heading('BETTER, TOGETHER','금액은 나만, 좋은 습관은 함께','서로의 흐름을 살펴보고, 부담 없이 조언을 나눠요.')}<div class="share-layout"><div>${sharePreview(payload)}</div><section class="panel"><div class="panel-header"><h2>이렇게만 공유돼요</h2><span class="tag green">공유 전 미리보기</span></div><div class="section-body"><div class="privacy-list"><span>${I('check')} 지출 분류별 비중</span><span>${I('check')} 수입 대비 사용하고 남긴 비중</span><span>${I('shield')} 실제 금액, 계좌명과 개별 거래는 제외</span></div><label class="share-option"><span>자산 종류별 비중도 보여주기<small>총액 없이 현금성·저축·투자 비중만 공개</small></span><input id="share-assets" type="checkbox" ${shareIncludeAssets?'checked':''}></label><label class="field"><span>링크 공개 기간</span><select class="input" id="share-days"><option value="1" ${shareDays===1?'selected':''}>1일</option><option value="7" ${shareDays===7?'selected':''}>7일</option><option value="30" ${shareDays===30?'selected':''}>30일</option></select></label><p class="subtle" style="margin:17px 0">링크를 받은 사람은 비중 자료를 볼 수 있어요. 로그인하면 댓글로 조언을 남길 수 있어요. 공유 시점의 자료가 저장되며, 가계부를 수정해도 기존 공유가 자동으로 바뀌지 않아요.</p><button class="btn primary" data-action="create-share" style="width:100%">${I('sharing')} 공유 링크 만들기</button>${!session.authenticated?'<p class="subtle" style="margin-top:10px">링크 공유는 로그인한 내 가계부에서 사용할 수 있어요.</p>':''}<div class="settings-buttons" style="display:flex;gap:8px;margin-top:11px"><button class="btn" data-action="export-safe-share" style="flex:1">비중 자료 JSON</button><button class="btn" data-action="open-friend" style="flex:1">친구 링크 열기</button></div></div></section></div><section class="panel share-history"><div class="panel-header"><h2>내가 공유한 자료</h2><button class="text-btn" data-action="load-shares">새로고침 ${I('chevron')}</button></div><div style="padding-top:12px">${shareRows.length?shareRows.map(r=>{const expired=r.revoked_at||r.expires_at<=new Date().toISOString();return`<div class="share-history-row"><div><strong>${dateLabel(koreanDate(r.created_at))}에 만든 비중 자료</strong><small>${expired?'공유 종료':dateLabel(koreanDate(r.expires_at))+'까지 공개'}</small></div><div>${memoryLinks[r.id]&&!expired?`<button class="btn small" data-action="copy-share" data-id="${esc(r.id)}">링크 복사</button>`:''}<button class="btn small" data-action="revoke-share" data-id="${esc(r.id)}" ${expired?'disabled':''}>공유 종료</button></div></div>`;}).join(''):empty('공유는 선택한 순간에만 시작돼요','자료를 미리 확인하고, 친구에게 링크를 건네보세요.')}</div></section>`;}
function sharedView(){if(sharedError)return`${heading('SHARED MOMENTS','공유 자료를 열 수 없어요','종료되었거나 만료된 링크일 수 있어요.')}<div class="panel">${empty(esc(sharedError),'친구에게 새로운 공유 링크를 요청해 주세요.')}<div class="section-body" style="text-align:center"><button class="btn" data-action="return-book">내 가계부로 돌아가기</button></div></div>`;if(!shared)return'<div class="empty">친구의 비중 자료를 불러오고 있어요.</div>';return`<div class="share-welcome"><span class="eyebrow" style="text-align:center">A LITTLE FINANCIAL STORY</span><h1>함께 보면, 더 좋은 흐름.</h1><p class="subtle">금액 없이 공유된 자료예요. 습관과 비중에 대해 이야기해 보세요.</p>${sharePreview(shared.payload)}<section class="panel" style="margin-top:22px"><div class="panel-header"><h2>서로를 위한 작은 조언</h2><span class="tag green">${shared.comments.length}개의 이야기</span></div><div style="padding-top:15px">${shared.comments.map(c=>`<div class="shared-comment"><span class="avatar">${esc(c.nickname.slice(0,1))}</span><div><strong>${esc(c.nickname)}</strong><time>${dateShort(koreanDate(c.createdAt))}</time><p>${esc(c.text)}</p></div>${c.canDelete?`<button data-action="delete-comment" data-id="${esc(c.id)}" aria-label="내 댓글 삭제">${I('close')}</button>`:''}</div>`).join('')||empty('첫 번째 응원을 남겨보세요','숫자보다 좋은 습관에 대한 조언을 나눠요.')}</div>${session.authenticated?`<form class="comment-form" id="comment-form"><div class="form-grid"><label class="field full"><span>함께 볼 별명</span><input class="input" name="nickname" required maxlength="24" placeholder="24자 이내의 별명" value="함께 보는 친구"></label><label class="field full"><span>나누고 싶은 조언</span><textarea class="input" name="text" required maxlength="500" placeholder="비중과 습관에 대해 따뜻한 조언을 남겨보세요."></textarea></label></div><div class="form-actions"><span class="subtle">실제 금액이나 개인정보는 적지 않아요.</span><button class="btn primary" type="submit">조언 남기기</button></div></form>`:`<div class="comment-form"><p class="subtle">로그인하면 친구에게 조언을 남길 수 있어요.</p><a class="btn green" style="margin-top:12px" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/moaflow/?share='+shareToken)}" target="_top">ChatGPT 계정으로 로그인</a></div>`}</section><div style="text-align:center;margin-top:22px"><button class="text-btn" data-action="return-book">나도 내 흐름 기록하기 →</button></div></div>`;}
function settingsView(){return`${heading('MAKE IT YOURS',ledgerBrand.embedded?'나에게 맞는 가계부':'나에게 맞는 모아흐름','가계부 이름부터 알림까지, 내 생활에 맞춰보세요.')}<div class="settings-layout"><section class="panel"><div class="settings-section"><h3>계정과 저장</h3><p>${session.authenticated?`${esc(session.user.name)} 계정으로 로그인했어요. 내 가계부는 계정별 저장 공간에 저장되고, 같은 계정으로 다른 기기에서 불러올 수 있어요.`:'현재는 이 브라우저에 저장하고 있어요. 로그인하면 다른 기기에서도 같은 가계부를 열고, 비중 자료를 링크로 공유할 수 있어요.'}</p>${session.authenticated?`<button class="btn" data-action="signout">로그아웃</button> <button class="btn" data-action="import-browser">이 브라우저 자료 가져오기</button>`:`<a class="btn green" href="${session.signInUrl||'/signin-with-chatgpt?return_to=%2Fmoaflow%2F'}" target="_top">ChatGPT 계정으로 로그인</a>`}${state.sample?'<p class="subtle" style="margin-top:12px">예시 모드는 실제 가계부와 분리해서 저장해요.</p>':''}</div><div class="settings-section"><h3>나의 가계부</h3><form id="settings-form"><div class="form-grid">${field('가계부 이름',input('name',state.book.name,'text','required maxlength="60"'),true)}${field('기록 시작일',input('openingDate',state.book.openingDate,'date','required'))}${field('월 지출 목표 (원)',input('budget',state.settings.monthlyBudget,'number','required min="0" max="1000000000000" step="1"'))}</div><p class="subtle" style="margin-top:10px">시작일은 가장 오래된 거래보다 앞이거나 같아야 해요. 기초 잔액은 이 날짜를 기준으로 해요.</p><div class="form-actions"><button class="btn primary">설정 저장</button></div></form></div><div class="settings-section"><h3>분류 관리</h3><p>나만의 이름으로 기록하고, 정기 지출과 일상 지출을 나눠요.</p><div class="category-manager">${state.categories.map(c=>`<button data-action="category-edit" data-id="${esc(c.id)}"><i class="bullet ${c.color}"></i><span>${esc(c.name)}</span><small>${c.type==='income'?'수입':c.group==='fixed'?'정기 지출':'일상 지출'}</small>${I('edit')}</button>`).join('')}</div><div class="settings-buttons"><button class="btn" data-action="new-category">${I('plus')} 분류 추가</button></div></div></section><section class="panel"><div class="settings-section"><h3>구독 알림</h3><p>다가오는 결제를 앱 안에서 확인하고, 캘린더로 받아볼 수 있어요. 브라우저 알림은 이 화면이 열려 있을 때 확인해요.</p><div class="share-option"><span>이 브라우저 알림<small>허용한 뒤 결제 알림을 확인해요.</small></span><button class="switch" role="switch" aria-label="브라우저 결제 알림" aria-checked="${state.settings.notifications}" data-action="enable-notifications"></button></div><div class="settings-buttons"><button class="btn" data-action="notifications">${I('bell')} 다가오는 알림</button><button class="btn" data-action="calendar-export">${I('calendar')} 캘린더에 추가</button></div><div class="form-info">앱과 알림 서비스에 연결할 수 있도록 준비했어요. 앱을 닫았을 때 받는 알림은 추후 연결 후 사용할 수 있어요.</div></div><div class="settings-section"><h3>백업과 복원</h3><p>전체 백업에는 금액과 거래내역이 포함돼요. 친구에게는 ‘함께 보기’의 비중 자료를 공유해 주세요.</p><div class="settings-buttons"><button class="btn" data-action="export-backup">${I('download')} 전체 백업 JSON</button><button class="btn" data-action="import-backup">${I('upload')} 백업 복원</button></div><input type="file" id="backup-file" accept=".json,application/json" hidden></div><div class="settings-section"><h3>처음처럼, 새롭게</h3><p>예시 가계부로 기능을 둘러보거나, 새 기록을 시작할 수 있어요. 현재 자료가 있다면 먼저 백업을 저장해 주세요.</p><div class="settings-buttons"><button class="btn" data-action="try-demo">예시로 둘러보기</button><button class="btn danger" data-action="reset-real">내 가계부 초기화</button></div></div><div class="settings-section"><h3>기록의 원칙</h3><p>수입과 지출, 자산과 부채를 함께 연결하는 복식부기 방식이에요. 투자금 이동이나 카드대금 납부를 지출로 중복 계산하지 않아요. 자산가치 변화는 수입·지출과 구분해요.</p></div></section></div>`;}
function field(label,html,full=false,hint=''){return`<label class="field ${full?'full':''}"><span>${label}</span>${html}${hint?`<span class="subtle">${hint}</span>`:''}</label>`;}
function input(name,value='',type='text',attrs=''){return`<input class="input" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;}
function options(items,selected,label=a=>a.name){return items.map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(label(a))}</option>`).join('');}
function showModal(title,subtitle,html,wide=false){if(!$('#modal-root').children.length)lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button data-action="close-modal" aria-label="닫기">${I('close')}</button></header><div class="modal-body">${html}</div></section></div>`;$('#app').inert=true;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal input:not([type="hidden"]),.modal select,.modal-head button')?.focus());}
function closeModal(){modalType='';$('#modal-root').innerHTML='';$('#app').inert=false;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function formError(message){const el=$('#form-error');if(el)el.textContent=message;else toast(message);}
function confirm(title,body,action,id='',extra=''){modalType='confirm';showModal(title,'내용을 확인한 뒤 진행해 주세요.',`<p class="subtle">${body}</p>${extra}<div class="form-actions"><button class="btn" data-action="close-modal">취소</button><button class="btn danger" data-action="${action}" data-id="${esc(id)}">확인하고 진행</button></div>`);}

function openEntry(id,defaults={}){
 const existing=state.entries.find(e=>e.id===id),date=month===F.monthOf(F.today())?F.today():month+'-01',e=existing||{kind:'expense',date,amount:'',description:'',from:state.accounts.find(a=>a.type==='asset')?.id,to:state.accounts.find(a=>a.type==='asset')?.id,categoryId:'food',status:date>F.today()?'planned':'posted',memo:'',...defaults};modalType='entry';
 showModal(existing?'거래 기록 수정':e.kind==='valuation'?'자산가치 기록':'새로운 거래 기록','쉬운 말로 입력하면 재무제표에 함께 반영돼요.',`<form id="entry-form" data-id="${esc(existing?.id||'')}"><div class="form-grid">${field('어떤 기록인가요?',`<select class="input" name="kind" id="entry-kind">${Object.entries(F.KIND_LABELS).map(([id,label])=>`<option value="${id}" ${e.kind===id?'selected':''}>${label}</option>`).join('')}</select>`)}${field('날짜',input('date',e.date,'date',`required min="${state.book.openingDate}" max="2100-12-31" id="entry-date"`))}${field('<span id="entry-amount-label">금액</span> (원)',input('amount',e.kind==='valuation'?e.targetBalance??'':e.amount,'number','required min="0" max="1000000000000" step="1"'))}${field('기록 상태',`<select class="input" name="status"><option value="posted" ${e.status==='posted'?'selected':''}>기록 완료</option><option value="planned" ${e.status==='planned'?'selected':''}>예정 · 합계에서 제외</option></select>`)}<div id="entry-dynamic" class="field full"></div>${field('어떤 내용인가요?',input('description',e.description,'text','required maxlength="120" placeholder="예: 점심 식사, 이번 달 급여"'),true)}${field('메모',`<textarea class="input" name="memo" maxlength="500" placeholder="필요한 내용만 남겨보세요.">${esc(e.memo||'')}</textarea>`,true)}</div><div class="form-info" id="entry-kind-hint"></div><div id="form-error" class="form-error" role="alert"></div><div class="form-actions">${existing?`<button class="btn danger" type="button" data-action="delete-entry" data-id="${esc(existing.id)}">기록 삭제</button>`:''}<button class="btn" type="button" data-action="close-modal">취소</button><button class="btn primary">${existing?'수정 저장':'기록 저장'}</button></div></form>`);
 updateEntryFields(e);
}
function updateEntryFields(previous={}){
 const f=$('#entry-form');if(!f)return;const current=Object.fromEntries(new FormData(f)),e={...previous,...current},kind=current.kind,assets=state.accounts.filter(a=>a.type==='asset'),debts=state.accounts.filter(a=>a.type==='liability');
 let html='';const select=(name,items,chosen)=>`<select class="input" required name="${name}">${options(items,chosen)}</select>`;
 if(kind==='income')html=field('받은 계좌',select('to',assets,e.to))+field('수입 분류',select('categoryId',state.categories.filter(c=>c.type==='income'),e.categoryId));
 if(kind==='expense')html=field('결제한 계좌·카드',select('from',state.accounts,e.from))+field('지출 분류',select('categoryId',state.categories.filter(c=>c.type==='expense'),e.categoryId));
 if(['transfer','repayment','borrow'].includes(kind))html=field(kind==='borrow'?'빌린 곳':'나간 계좌',select('from',kind==='borrow'?debts:assets,e.from))+field(kind==='repayment'?'갚을 카드·대출':'받은 계좌',select('to',kind==='repayment'?debts:assets,e.to));
 if(kind==='valuation')html=field('가치를 갱신할 계좌',select('accountId',state.accounts,e.accountId||assets[0]?.id),true);
 $('#entry-dynamic').innerHTML=`<div class="form-grid">${html}</div>`;
 $('#entry-amount-label').textContent=kind==='valuation'?'갱신 후 전체 평가액':'금액';f.elements.amount.min=kind==='valuation'?'0':'1';
 const hints={income:'실제로 받은 수입을 기록해요. 아직 받을 예정이라면 상태를 ‘예정’으로 선택해 주세요.',expense:'카드로 결제했다면 해당 카드를 선택해요. 지출과 카드 미결제액이 함께 늘어나요.',transfer:'저축·투자 계좌로 옮긴 돈도 이체예요. 내 자산 사이의 이동이라 지출이나 순자산 증가로 중복 계산하지 않아요.',repayment:'카드값이나 대출 원금을 갚으면 현금과 부채가 함께 줄어요. 이미 기록한 지출을 다시 더하지 않아요. 이자는 별도 지출로 기록해요.',borrow:'빌린 돈이 계좌로 들어오고, 갚을 부채도 함께 생겨요. 내 수입으로 계산하지 않아요.',valuation:'해당 날짜의 전체 잔액·평가액을 입력해요. 이전 기록에서의 변화는 수입·지출과 구분해 순자산에 반영돼요.'};$('#entry-kind-hint').textContent=hints[kind];
}
function openSubscription(id){const s=state.subscriptions.find(s=>s.id===id),r=s||{name:'',amount:'',cadence:'monthly',anchorDate:F.today(),accountId:state.accounts.find(a=>a.type==='liability')?.id||state.accounts[0].id,categoryId:state.categories.find(c=>c.type==='expense'&&c.id==='subscription')?.id||state.categories.find(c=>c.type==='expense')?.id,active:true,remindDays:3,color:'green',memo:''};modalType='subscription';
 showModal(s?'구독 상세와 결제일':'새로운 구독 추가','한 번의 등록으로 다음 결제를 편하게 챙겨요.',`<form id="subscription-form" data-id="${esc(id||'')}"><div class="form-grid">${field('구독 이름',input('name',r.name,'text','required maxlength="60" placeholder="예: 음악 스트리밍"'),true)}${field('결제 금액 (원)',input('amount',r.amount,'number','required min="1" max="1000000000000" step="1"'))}${field('결제 주기',`<select name="cadence" class="input"><option value="monthly" ${r.cadence==='monthly'?'selected':''}>매월</option><option value="yearly" ${r.cadence==='yearly'?'selected':''}>매년</option></select>`)}${field('기준 결제일',input('anchorDate',r.anchorDate,'date','required'),'','이 날짜의 일자를 기준으로 반복해요. 해당 일자가 없는 달은 말일이에요.')}${field('결제할 계좌·카드',`<select name="accountId" required class="input">${options(state.accounts,r.accountId)}</select>`)}${field('지출 분류',`<select name="categoryId" required class="input">${options(state.categories.filter(c=>c.type==='expense'),r.categoryId)}</select>`)}${field('며칠 전에 챙길까요?',`<select name="remindDays" class="input">${[0,1,3,7,14].map(n=>`<option value="${n}" ${r.remindDays===n?'selected':''}>${n===0?'당일':n+'일 전'}</option>`).join('')}</select>`)}${field('사용 여부',`<select name="active" class="input"><option value="true" ${r.active?'selected':''}>사용 중</option><option value="false" ${!r.active?'selected':''}>일시정지</option></select>`)}${field('카드 색상',`<select name="color" class="input">${F.COLORS.map(c=>`<option value="${c}" ${r.color===c?'selected':''}>${({blue:'파랑',green:'초록',purple:'보라',orange:'살구',pink:'분홍',cyan:'하늘'})[c]}</option>`).join('')}</select>`)}${field('메모',input('memo',r.memo,'text','maxlength="200"'),true)}</div><div class="form-info">구독을 추가해도 지출이 자동으로 기록되지는 않아요. 결제된 뒤 ‘결제 기록’을 누르면 가계부에 반영돼요. 금액이나 결제일을 수정해도 이미 연결한 결제 기록은 유지해요. 월간은 같은 월, 연간은 같은 연도에 연결한 기록이 있으면 새 결제를 만들지 않아요.</div><div id="form-error" class="form-error" role="alert"></div><div class="form-actions">${s?`<button class="btn danger" type="button" data-action="delete-subscription" data-id="${esc(id)}">구독 삭제</button>`:''}<button class="btn" type="button" data-action="close-modal">취소</button><button class="btn primary">${s?'수정 저장':'구독 추가'}</button></div></form>`);
}
function openCharge(id,date){const s=state.subscriptions.find(s=>s.id===id);if(!s)return;const recorded=state.entries.find(e=>e.subscriptionId===id&&e.scheduledDate===date),charge={name:recorded?.description??s.name,amount:recorded?.amount??s.amount,accountId:recorded?.from??s.accountId};modalType='charge';showModal('구독 결제를 기록할까요?',`${charge.name} · ${dateLabel(date)} 예정 결제`,`<div class="modal-amount"><small>${esc(charge.name)}</small>${money(charge.amount)}</div><form id="charge-form" data-id="${esc(id)}" data-date="${date}">${field('실제로 결제한 날짜',input('actualDate',F.today(),'date',`required min="${state.book.openingDate}" max="${F.today()}"`),true)}<div class="form-info">${esc(accountName(charge.accountId))}에서 결제한 지출로 기록해요. 같은 예정 결제를 두 번 기록하지 않아요.</div><div id="form-error" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">취소</button><button class="btn primary">결제 기록하기</button></div></form>`);}
function openAccount(id){const a=account(id);if(!a)return;const balance=F.ledger(state).balances[id],related=state.entries.filter(e=>[e.from,e.to,e.accountId].includes(id)).sort((a,b)=>b.date.localeCompare(a.date)||b.order-a.order).slice(0,5);modalType='account';showModal(a.name,F.ASSET_GROUPS[a.group],`<div class="modal-amount"><small>${a.type==='asset'?'현재 기록된 평가액':'현재 남은 부채'}</small>${money(balance)}</div><button class="btn green" data-action="valuation-account" data-id="${esc(id)}">${I('plus')} 현재 가치·잔액 갱신</button><form id="account-form" data-id="${esc(id)}" style="margin-top:23px"><div class="form-grid">${field('계좌 이름',input('name',a.name,'text','required maxlength="60"'),true)}${field('종류',`<select class="input" name="group">${Object.entries(F.ASSET_GROUPS).filter(([id])=>a.type==='liability'?['card','loan'].includes(id):!['card','loan'].includes(id)).map(([id,name])=>`<option value="${id}" ${a.group===id?'selected':''}>${name}</option>`).join('')}</select>`)}${field('시작일 기준 기초 잔액 (원)',input('openingBalance',a.openingBalance,'number','required min="0" max="1000000000000" step="1"'),'','가계부 시작일 '+state.book.openingDate+'의 잔액이에요.')}${field('나만의 메모',input('memo',a.memo,'text','maxlength="200"'),true)}</div><div id="form-error" class="form-error" role="alert"></div><div class="form-actions"><button class="btn danger" type="button" data-action="delete-account" data-id="${esc(id)}">계좌 삭제</button><button class="btn" type="button" data-action="close-modal">닫기</button><button class="btn primary">정보 저장</button></div></form>${related.length?`<div class="form-info">최근 기록</div>${related.map(detailEntry).join('')}`:''}`);}
function newAccount(){modalType='new-account';showModal('나의 계좌 추가','입출금 통장, 투자, 저축과 부채를 함께 관리해요.',`<form id="new-account-form"><div class="form-grid">${field('계좌 이름',input('name','','text','required maxlength="60" placeholder="예: 비상금 통장"'),true)}${field('종류',`<select class="input" name="group">${Object.entries(F.ASSET_GROUPS).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select>`)}${field('시작일 기초 잔액 (원)',input('openingBalance',0,'number','required min="0" max="1000000000000" step="1"'),'','가계부 시작일 '+state.book.openingDate+'의 잔액이에요.')}${field('메모',input('memo','','text','maxlength="200"'),true)}</div><div class="form-info">지금의 평가액을 남기려면 계좌를 만든 뒤 ‘현재 가치·잔액 갱신’으로 기록해 주세요.</div><div id="form-error" class="form-error" role="alert"></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">취소</button><button class="btn primary">계좌 추가</button></div></form>`);}
function openCategoryEdit(id){const c=category(id),r=c||{name:'',type:'expense',group:'variable',shareGroup:'기타',color:'purple'};modalType='category-edit';showModal(c?'분류 이름과 성격':'새 분류 추가','내 기록에 맞게 정기 지출과 일상 지출을 나눠요.',`<form id="category-form" data-id="${esc(id||'')}"><div class="form-grid">${field('분류 이름',input('name',r.name,'text','required maxlength="40"'),true)}${field('수입·지출',`<select name="type" class="input"><option value="income" ${r.type==='income'?'selected':''}>수입</option><option value="expense" ${r.type==='expense'?'selected':''}>지출</option></select>`)}${field('지출 성격',`<select class="input" name="group"><option value="variable" ${r.group==='variable'?'selected':''}>일상 지출</option><option value="fixed" ${r.group==='fixed'?'selected':''}>정기 지출</option></select>`)}${field('친구 공유 시 넓은 분류',`<select class="input" name="shareGroup">${F.SHARE_GROUPS.map(g=>`<option ${g===r.shareGroup?'selected':''}>${g}</option>`).join('')}</select>`,true,'친구에게는 실제 분류 이름 대신 이 넓은 분류만 보여요.')}</div><div id="form-error" class="form-error" role="alert"></div><div class="form-actions">${c?`<button class="btn danger" type="button" data-action="delete-category" data-id="${esc(id)}">분류 삭제</button>`:''}<button class="btn" type="button" data-action="close-modal">취소</button><button class="btn primary">저장</button></div></form>`);}
function detailEntry(e){return`<div class="detail-entry"><time>${dateShort(e.date)}</time><div><strong>${esc(e.description)}</strong><small>${esc(entryRoute(e))}</small></div><span>${money(e.kind==='valuation'?e.targetBalance:e.amount)}</span><button data-action="entry" data-id="${esc(e.id)}" aria-label="${esc(e.description)} 수정">${I('edit')}</button></div>`;}
function openDetails(title,entries,subtitle='선택한 월의 기록을 살펴보고 바로 수정할 수 있어요.',categoryId=''){
 modalType='details';const sum=entries.reduce((n,e)=>n+(e.kind==='valuation'?0:e.amount),0);showModal(title,subtitle,`<div class="modal-amount"><small>${entries.length}개 기록</small>${money(sum)}</div>${[...entries].sort((a,b)=>b.date.localeCompare(a.date)||b.order-a.order).map(detailEntry).join('')||empty('해당하는 기록이 없어요','새 기록을 남겨보세요.')}<div class="form-actions"><button class="btn" data-action="close-modal">닫기</button><button class="btn primary" data-action="${categoryId?'new-entry-category':'new-entry'}" data-id="${esc(categoryId)}">${I('plus')} 새 기록</button></div>`,true);
}
function openCategory(id){const c=category(id);if(!c)return;openDetails(c.name,F.monthly(state,month).entries.filter(e=>e.categoryId===id),`${month} · ${c.type==='income'?'수입':c.group==='fixed'?'정기 지출':'일상 지출'}`,id);}
function openRetained(){const m=F.monthly(state,month);modalType='retained';showModal('이번 달에 남긴 돈','수입에서 지출을 뺀, 나의 여유를 확인해요.',`<div class="statement-row"><span>이달 수입</span><strong>${money(m.income)}</strong></div><div class="statement-row"><span>이달 지출</span><strong>− ${money(m.expense)}</strong></div><div class="statement-row total"><span>남은 돈</span><strong>${money(m.net)}</strong></div><div class="form-info">남은 돈은 계좌 한 곳의 잔액과는 달라요. 저축·투자 계좌로 옮긴 돈과 카드 사용 후 남은 부채도 전체 자산·부채 안에서 함께 확인할 수 있어요.</div><div class="form-actions"><button class="btn" data-action="open-assets">내 자산 보기</button><button class="btn primary" data-action="open-statements">재무제표 보기</button></div>`);}
function openHistory(date){const l=F.ledger(state,date);modalType='history';showModal(dateLabel(date)+'의 자산 기록','선택한 날까지의 거래와 평가액을 반영한 값이에요.',`<div class="modal-amount"><small>순자산</small>${money(l.netAssets)}</div>${state.accounts.map(a=>`<button class="statement-row" style="width:100%" data-action="account" data-id="${esc(a.id)}"><span>${esc(a.name)}</span><strong>${money(l.balances[a.id])}</strong></button>`).join('')}<div class="form-actions"><button class="btn" data-action="close-modal">닫기</button><button class="btn primary" data-action="new-valuation">새 평가액 기록</button></div>`);}
function notifications(){modalType='notifications';const list=F.reminders(state);showModal('내가 챙길 구독 알림','미리 확인하면, 결제일도 가볍게.',`${list.map(r=>`<div class="notification-row">${tile('calendar',r.overdue?'orange':'green')}<div class="row-main"><strong>${esc(r.name)}</strong><small>${dateLabel(r.date)} ${r.overdue?'지난 결제 확인':'다가오는 결제'}</small></div><strong>${money(r.amount)}</strong><button data-action="subscription" data-id="${esc(r.subscriptionId)}" aria-label="${esc(r.name)} 상세">${I('chevron')}</button></div>`).join('')||empty('지금은 확인할 결제가 없어요','결제일이 가까워지면 이곳에 모아드려요.')}<div class="form-info">구독별로 설정한 알림일이 되면 보여요. 지나간 미확인 결제는 최근 14일까지 확인할 수 있어요.</div><div class="form-actions"><button class="btn" data-action="calendar-export">캘린더로 받기</button><button class="btn primary" data-action="open-subscriptions">구독 관리</button></div>`);}
function searchModal(){modalType='search';showModal('내 기록에서 찾아보기','거래, 구독과 계좌 이름을 검색해 보세요.',`<div class="search-field" style="width:100%;margin-bottom:15px">${I('search')}<input class="input" id="global-search" type="search" placeholder="무엇을 찾고 있나요?" aria-label="통합 검색어"></div><div id="search-results" class="search-results"></div>`);updateSearch('');}
function updateSearch(q){q=q.trim().toLowerCase();const accounts=state.accounts.filter(a=>(a.name+' '+a.memo).toLowerCase().includes(q)),subs=state.subscriptions.filter(s=>s.name.toLowerCase().includes(q)),entries=state.entries.filter(e=>(e.description+' '+e.memo+' '+categoryName(e.categoryId)).toLowerCase().includes(q)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20);$('#search-results').innerHTML=`${accounts.length?'<p class="search-section">계좌</p>':''}${accounts.map(a=>`<button class="search-result" data-action="account" data-id="${esc(a.id)}">${I('bank')}<span><strong>${esc(a.name)}</strong><small>${F.ASSET_GROUPS[a.group]}</small></span></button>`).join('')}${subs.length?'<p class="search-section">구독</p>':''}${subs.map(s=>`<button class="search-result" data-action="subscription" data-id="${esc(s.id)}">${I('subscriptions')}<span><strong>${esc(s.name)}</strong><small>${s.active?'사용 중':'일시정지'}</small></span></button>`).join('')}${entries.length?'<p class="search-section">거래 · 최근 일치 내역 최대 20개</p>':''}${entries.map(e=>`<button class="search-result" data-action="entry" data-id="${esc(e.id)}">${I('ledger')}<span><strong>${esc(e.description)}</strong><small>${e.date} · ${money(e.kind==='valuation'?e.targetBalance:e.amount)}</small></span></button>`).join('')}${!accounts.length&&!subs.length&&!entries.length?empty('일치하는 기록이 없어요','다른 이름이나 분류로 찾아보세요.'):''}`;}
function navigate(to){closeModal();if(shareToken){shareToken=null;shared=null;sharedError='';history.replaceState(null,'',ledgerBrand.home+'#'+to);render();}else if(location.hash==='#'+to)render();else location.hash=to;window.scrollTo({top:0,behavior:'instant'});if(to==='sharing')loadShares();}
function download(text,name,mime){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportBackup(){download(JSON.stringify(state,null,2),`모아흐름_전체백업_${F.today()}.json`,'application/json');toast('금액을 포함한 전체 백업을 저장했어요.');}
function exportCSV(){const rows=[['날짜','내용','종류','상태','출발','도착','분류','금액(원)','메모'],...state.entries.filter(e=>F.monthOf(e.date)===month).map(e=>[e.date,e.description,F.KIND_LABELS[e.kind],e.status,e.from?accountName(e.from):'',e.to?accountName(e.to):e.accountId?accountName(e.accountId):'',e.categoryId?categoryName(e.categoryId):'',e.kind==='valuation'?e.targetBalance:e.amount,e.memo||''])];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+\-@\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');download(csv,`모아흐름_거래_${month}.csv`,'text/csv;charset=utf-8');toast('이 달의 거래를 CSV로 저장했어요.');}
async function loadShares(){if(!session.authenticated||state.sample){shareRows=[];if(page==='sharing'&&!shareToken)render();return;}try{shareRows=(await api('shares')).shares;if(page==='sharing'&&!shareToken)render();}catch(error){toast(error.message);}}
async function createShare(){
 if(!session.authenticated||state.sample){showModal('내 가계부로 공유해요','예시 자료와 내 실제 자료는 분리해서 저장해요.',`<p class="subtle">${state.sample?'먼저 내 가계부를 시작해 주세요.':'로그인하면 금액을 숨긴 비중 자료를 공유할 수 있어요.'} 왼쪽 미리보기의 비중만 전달되며, 개별 거래나 실제 금액은 전달하지 않아요.</p><div class="form-actions"><button class="btn" data-action="close-modal">닫기</button>${session.authenticated?'<button class="btn primary" data-action="start-real">내 가계부로 돌아가기</button>':`<a class="btn green" target="_top" href="${session.signInUrl}">로그인하기</a>`}</div>`);return;}
 if(dirty){await saveCloud();if(dirty)return toast('가계부 저장을 마친 뒤 공유를 만들 수 있어요.');}
 try{const result=await api('shares',{method:'POST',body:{month,includeAssets:shareIncludeAssets,days:shareDays,confirm:true}});memoryLinks[result.id]=result.url;try{localStorage.setItem('moaflow:share-links:'+session.user.key,JSON.stringify(memoryLinks));}catch{}await loadShares();showShareLink(result.url,result.expiresAt);}catch(error){toast(error.message);}
}
function showShareLink(url,expiresAt){modalType='share-link';showModal('친구와 나눌 링크가 준비됐어요',expiresAt?dateLabel(koreanDate(expiresAt))+'까지 볼 수 있어요.':'비중 자료 링크',`${field('복사해서 친구에게 전달해 주세요.',input('shareUrl',url,'text','readonly id="share-url"'),true)}<div class="form-info">이 링크로는 비중 자료만 볼 수 있어요. 가계부 전체와 실제 금액에 접근할 수는 없어요. 공유 관리에서 언제든 종료할 수 있어요.</div><div class="form-actions"><button class="btn" data-action="close-modal">닫기</button><button class="btn primary" data-action="copy-link">${I('copy')} 링크 복사</button></div>`);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('링크를 복사했어요.');}catch{const field=$('#share-url');if(field){field.focus();field.select();toast('링크를 길게 눌러 복사해 주세요.');}else showShareLink(text);}}
async function loadShared(){shared=null;sharedError='';try{shared=await api('shares/'+encodeURIComponent(shareToken));}catch(error){sharedError=error.message;}render();}
function friendModal(){modalType='friend';showModal('친구의 비중 자료 열기','모아흐름에서 만든 링크를 붙여 넣어 주세요.',`<form id="friend-form">${field('친구의 공유 링크',input('url','','url','required placeholder="https://bandal.app/moaflow/?share=…"'),true)}<div id="form-error" class="form-error" role="alert"></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">취소</button><button class="btn primary">자료 열기</button></div></form>`);}
async function enableNotifications(){
 if(state.settings.notifications){state.settings.notifications=false;commit('브라우저 알림을 껐어요.');return;}
 if(!('Notification'in window)||!isSecureContext)return toast('브라우저 알림을 지원하는 HTTPS 환경에서 사용할 수 있어요. 캘린더 알림도 이용할 수 있어요.');
 const permission=await Notification.requestPermission();if(permission==='granted'){state.settings.notifications=true;commit('이 화면이 열려 있을 때 결제 알림을 확인해요.');checkNotifications();}else toast('브라우저에서 알림이 허용되지 않았어요. 캘린더로 결제일을 받아볼 수 있어요.');
}
function checkNotifications(){if(!state.settings.notifications||!('Notification'in window)||Notification.permission!=='granted')return;const delivered=read('moaflow:notification-seen')||{},list=F.reminders(state);for(const n of list){if(delivered[n.id])continue;const notice=new Notification(n.name+' 결제일 확인',{body:'모아흐름에서 구독 내역을 확인해 주세요.',tag:'moaflow-'+n.id,icon:'/moaflow/mark.svg'});notice.onclick=()=>{window.focus();navigate('subscriptions');notice.close();};delivered[n.id]=true;}try{localStorage.setItem('moaflow:notification-seen',JSON.stringify(delivered));}catch{}}

async function startReal(){
 closeModal();syncError='';dirty=false;
 if(session.authenticated){const data=await api('state');state=data.state?F.validateState(data.state):F.blankState();revision=data.revision;saveStatus=data.state?'계정에 저장됨':'내 가계부를 시작해요';}
 else{const stored=inspectBrowserLedger();if(stored.status==='invalid')return askBrowserRecovery();state=stored.status==='valid'?stored.record.state:F.blankState();state.sample=false;revision=0;saveStatus='이 브라우저에 저장';}
 persist();navigate('dashboard');toast('나의 기록을 시작해 보세요.');
}
async function reloadCloud(){
 if(!session.authenticated)return;
 const data=await api('state');state=data.state?F.validateState(data.state):F.blankState();revision=data.revision;dirty=false;syncError='';saveStatus='계정에 저장됨';persist();closeModal();render();toast('최신 자료를 불러왔어요.');
}
async function handleAction(action,id,el){
 if(accountChanged&&!['close-modal','export-backup','reload-session'].includes(action))return toast('현재 계정을 다시 확인한 뒤 이용해 주세요.');
 switch(action){
  case'reload-session':location.reload();break;
  case'close-modal':closeModal();break;
  case'new-entry':openEntry();break;
  case'entry':openEntry(id);break;
  case'new-valuation':openEntry(null,{kind:'valuation',date:F.today(),description:'자산 평가액 갱신',accountId:state.accounts.find(a=>a.type==='asset')?.id,status:'posted'});break;
  case'valuation-account':openEntry(null,{kind:'valuation',date:F.today(),description:accountName(id)+' 평가액 갱신',accountId:id,targetBalance:F.ledger(state).balances[id],status:'posted'});break;
  case'new-entry-category':openEntry(null,{kind:category(id)?.type||'expense',categoryId:id});break;
  case'new-subscription':openSubscription();break;
  case'subscription':openSubscription(id);break;
  case'new-account':newAccount();break;
  case'account':openAccount(id);break;
  case'new-category':openCategoryEdit();break;
  case'category-edit':openCategoryEdit(id);break;
  case'category':openCategory(id);break;
  case'kind-detail':openDetails(id==='income'?'이달의 수입':'이달의 지출',F.monthly(state,month).entries.filter(e=>e.kind===id));break;
  case'group-detail':openDetails(id==='fixed'?'정기 지출의 세부 흐름':'일상 지출의 세부 흐름',F.monthly(state,month).entries.filter(e=>e.kind==='expense'&&category(e.categoryId)?.group===id));break;
  case'all-income':openDetails('이달의 수입',F.monthly(state,month).entries.filter(e=>e.kind==='income'));break;
  case'retained':openRetained();break;
  case'shortage':showModal('이달의 지출이 수입보다 많아요','수입 외의 자금이 필요한 부분을 표시했어요.',`<div class="modal-amount"><small>수입보다 더 사용한 금액</small>${money(-F.monthly(state,month).net)}</div><p class="subtle">기존 현금이나 저축을 사용했거나, 카드 미결제액과 같은 부채가 늘어났을 수 있어요. 자산·부채와 거래 기록을 함께 확인해 주세요.</p><div class="form-actions"><button class="btn primary" data-action="open-assets">자산과 부채 보기</button></div>`);break;
  case'open-assets':navigate('assets');break;
  case'open-settings':navigate('settings');break;
  case'open-statements':navigate('statements');break;
  case'open-subscriptions':navigate('subscriptions');break;
  case'asset-group':openHistory(F.monthEnd(month)>F.today()?F.today():F.monthEnd(month));break;
  case'history-point':openHistory(id);break;
  case'flow-view':flowView=id;render();break;
  case'river-node':openRiverDetails(id);break;
  case'river-expand':riverExpanded=riverExpanded===id?null:id;render();break;
  case'river-focus':flowAccountId=id;riverExpanded='group:fixed';closeModal();flowView='accounts';navigate('dashboard');break;
  case'river-add':addRiverEntry(id);break;
  case'river-first-income':openEntry(null,{kind:'income',to:flowAccountId,categoryId:state.categories.find(c=>c.type==='income')?.id});break;
  case'river-motion':motionPaused=!motionPaused;syncRiverMotion(document,motionPaused);el.setAttribute('aria-pressed',String(motionPaused));el.innerHTML=I(motionPaused?'play':'pause')+'<span>'+(motionPaused?'움직임 재생':'움직임 멈추기')+'</span>';const live=$('.river-live');if(live){live.innerHTML='<i></i>'+(motionPaused?'STILL':'LIVE FLOW');live.classList.toggle('running',!motionPaused);}break;
  case'month-prev':month=F.shiftMonth(month,-1);entryPage=0;render();break;
  case'month-next':month=F.shiftMonth(month,1);entryPage=0;render();break;
  case'select-month':month=id;entryPage=0;render();break;
  case'entries-prev':entryPage=Math.max(0,entryPage-1);$('#ledger-table-region').innerHTML=ledgerTable();break;
  case'entries-next':entryPage++;$('#ledger-table-region').innerHTML=ledgerTable();break;
  case'subscription-filter':subscriptionFilter=id;render();break;
  case'toggle-subscription':{const s=state.subscriptions.find(s=>s.id===id);s.active=!s.active;commit(s.active?'구독을 다시 사용해요.':'구독을 일시정지했어요.');break;}
  case'charge-subscription':openCharge(id,el.dataset.date);break;
  case'all-subscriptions':openDetails('구독으로 기록한 지출',F.monthly(state,month).entries.filter(e=>e.subscriptionId));break;
  case'month-subscriptions':{const events=F.subscriptionEvents(state,month+'-01',F.monthEnd(month));showModal('이 달의 구독 결제',`${month} · ${events.length}건`,events.map(s=>`<div class="notification-row"><span class="service-icon ${s.color}">${esc(s.name.slice(0,1))}</span><div class="row-main"><strong>${esc(s.name)}</strong><small>${dateLabel(s.date)} · ${s.paid?'기록 완료':'아직 미확인'}</small></div><strong>${money(s.amount)}</strong>${!s.paid&&s.date<=F.today()?`<button class="btn small green" data-action="charge-subscription" data-id="${esc(s.id)}" data-date="${s.date}">결제 기록</button>`:''}</div>`).join('')||empty('이 달에는 결제 일정이 없어요','구독과 조회할 월을 확인해 주세요.'));break;}
  case'notifications':notifications();break;
  case'enable-notifications':await enableNotifications();break;
  case'toggle-amounts':state.settings.hideAmounts=!state.settings.hideAmounts;commit(state.settings.hideAmounts?'화면의 금액을 숨겼어요.':'화면의 금액을 표시해요.');break;
  case'search':searchModal();break;
  case'export-backup':exportBackup();break;
  case'export-csv':exportCSV();break;
  case'calendar-export':download(F.calendarICS(state),`모아흐름_구독결제일_${F.today()}.ics`,'text/calendar;charset=utf-8');toast('결제일과 알림이 담긴 캘린더 파일을 저장했어요.');break;
  case'import-backup':$('#backup-file')?.click();break;
  case'export-safe-share':download(JSON.stringify(F.safeShare(state,month,shareIncludeAssets),null,2),`모아흐름_비중자료_${month}.json`,'application/json');toast('금액 없이 비중 자료만 저장했어요.');break;
  case'create-share':await createShare();break;
  case'load-shares':await loadShares();break;
  case'copy-share':if(memoryLinks[id])showShareLink(memoryLinks[id]);break;
  case'copy-link':await copyText($('#share-url')?.value||'');break;
  case'open-friend':friendModal();break;
  case'return-book':navigate('dashboard');break;
  case'revoke-share':confirm('이 공유를 종료할까요?','종료하면 이전 링크로 비중 자료와 댓글을 볼 수 없어요. 필요하면 새 공유를 만들 수 있어요.','confirm-revoke-share',id);break;
  case'confirm-revoke-share':await api('shares/'+encodeURIComponent(id)+'/revoke',{method:'POST',body:{}});closeModal();await loadShares();toast('공유를 종료했어요.');break;
  case'delete-comment':confirm('이 조언을 지울까요?','이 댓글을 공유 자료에서 삭제해요.','confirm-delete-comment',id);break;
  case'confirm-delete-comment':await api(`shares/${encodeURIComponent(shareToken)}/comments/${encodeURIComponent(id)}`,{method:'DELETE'});closeModal();await loadShared();toast('댓글을 삭제했어요.');break;
  case'delete-entry':confirm('이 거래 기록을 삭제할까요?','연결된 계좌와 재무제표를 다시 계산해요. 구독 결제라면 해당 일정이 미확인 상태로 돌아가요.','confirm-delete-entry',id);break;
  case'confirm-delete-entry':state.entries=state.entries.filter(e=>e.id!==id);closeModal();commit('거래를 지우고 흐름을 다시 계산했어요.');break;
  case'delete-account':if(state.accounts.length<=1)return formError('최소 한 개의 계좌가 필요해요.');if(state.entries.some(e=>[e.from,e.to,e.accountId].includes(id))||state.subscriptions.some(s=>s.accountId===id))return formError('연결된 거래나 구독이 있어요. 먼저 다른 계좌로 옮겨 주세요.');confirm('계좌를 삭제할까요?','계좌의 이름과 기초 잔액을 지워요.','confirm-delete-account',id);break;
  case'confirm-delete-account':state.accounts=state.accounts.filter(a=>a.id!==id);closeModal();commit('계좌를 삭제했어요.');break;
  case'delete-subscription':confirm('구독을 삭제할까요?','앞으로의 결제 일정이 사라져요. 이미 기록한 지출은 가계부에 남아요.','confirm-delete-subscription',id);break;
  case'confirm-delete-subscription':state.entries=state.entries.map(e=>{if(e.subscriptionId!==id)return e;const c={...e};delete c.subscriptionId;delete c.scheduledDate;return c;});state.subscriptions=state.subscriptions.filter(s=>s.id!==id);closeModal();commit('구독을 삭제했어요.');break;
  case'delete-category':if(state.entries.some(e=>e.categoryId===id)||state.subscriptions.some(s=>s.categoryId===id))return formError('사용 중인 분류예요. 연결된 기록을 먼저 변경해 주세요.');confirm('분류를 삭제할까요?','이 분류를 기록 선택지에서 지워요.','confirm-delete-category',id);break;
  case'confirm-delete-category':state.categories=state.categories.filter(c=>c.id!==id);closeModal();commit('분류를 삭제했어요.');break;
  case'start-real':await startReal();break;
  case'download-browser-original':{let raw=null;try{raw=localStorage.getItem(REAL_KEY);}catch{}if(raw===null)return toast('내려받을 원본이 없어요.');download(raw,`모아흐름_브라우저원본_${F.today()}.txt`,'text/plain');toast('읽을 수 없던 원본을 그대로 내려받았어요.');break;}
  case'confirm-keep-browser-original':{if(inspectBrowserLedger().status!=='invalid'){closeModal();break;}F.keepUnreadableLedger(localStorage,REAL_KEY);inspectBrowserLedger();closeModal();if(state.sample)await startReal();else commit('원본을 따로 보관하고 지금 가계부를 저장했어요.');break;}
  case'try-demo':if(dirty){await saveCloud();if(dirty)return toast('저장이나 백업을 마친 뒤 예시를 열어 주세요.');}persist();state=F.demoState();dirty=false;syncError='';saveStatus='예시로 체험 중';navigate('dashboard');break;
  case'reset-real':confirm('내 가계부를 새롭게 시작할까요?','현재 가계부의 거래·구독·계좌를 지우고 기본 계좌로 시작해요. 필요한 내용은 먼저 전체 백업으로 저장해 주세요. 이전에 만든 공유 자료는 공유 관리에서 따로 종료할 수 있어요.','confirm-reset-real','','<div class="form-actions"><button class="btn" data-action="export-backup">먼저 전체 백업</button></div>');break;
  case'confirm-reset-real':if(session.authenticated)revision=(await api('state')).revision;state=F.blankState();syncError='';closeModal();commit('새 가계부를 시작해요.');break;
  case'reload-cloud':confirm('계정의 최신 자료를 불러올까요?','이 기기에서 아직 전송하지 못한 수정 내용은 교체돼요. 먼저 전체 백업을 저장하면 안전하게 보관할 수 있어요.','confirm-reload-cloud','','<div class="form-actions"><button class="btn" data-action="export-backup">내 수정본 백업</button> <button class="btn green" data-action="retry-sync">내 변경 다시 저장</button></div>');break;
  case'confirm-reload-cloud':await reloadCloud();break;
  case'retry-sync':syncError='';closeModal();await saveCloud();render();break;
  case'import-browser':{const cached=read(REAL_KEY);if(!cached?.state)return toast('이 브라우저에 가져올 실제 가계부가 없어요.');F.validateState(cached.state);confirm('브라우저 가계부를 계정으로 가져올까요?','현재 계정의 가계부를 이 브라우저의 자료로 교체해요. 필요한 계정 자료는 먼저 백업해 주세요.','confirm-import-browser');break;}
  case'confirm-import-browser':{const cached=read(REAL_KEY);if(!cached?.state)return;state=F.validateState(structuredClone(cached.state));state.sample=false;syncError='';revision=(await api('state')).revision;closeModal();commit('브라우저 가계부를 계정에 저장하고 있어요.');break;}
  case'signout':if(dirty){await saveCloud();if(dirty)return toast('아직 계정에 전송하지 못한 기록이 있어요. 백업하거나 동기화를 마친 뒤 로그아웃해 주세요.');}try{localStorage.removeItem(cloudKey());}catch{}if(ledgerBrand.embedded)window.top.location.assign(session.signOutUrl);else location.href=session.signOutUrl;break;
 }
}
document.addEventListener('click',async event=>{
 if(event.target.classList.contains('modal-backdrop'))return closeModal();
 const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();
 try{if(!accountChanged&&el.dataset.action==='kind-detail'){const kind=el.dataset.id;openDetails(kind==='income'?'이달의 수입':'이달의 지출',F.monthly(state,month).entries.filter(e=>e.kind===kind));return;}await handleAction(el.dataset.action,el.dataset.id,el);}catch(error){toast(error.message||'잠시 후 다시 시도해 주세요.');}
});
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.id==='month-picker'){if(/^\d{4}-(0[1-9]|1[0-2])$/.test(el.value)){month=el.value;entryPage=0;render();}}
 if(el.id==='river-account'){flowAccountId=el.value;riverExpanded='group:fixed';render();}
 if(el.id==='entry-kind-filter'){entryType=el.value;entryPage=0;$('#ledger-table-region').innerHTML=ledgerTable();}
 if(el.id==='entry-status-filter'){entryStatus=el.value;entryPage=0;$('#ledger-table-region').innerHTML=ledgerTable();}
 if(el.id==='entry-kind')updateEntryFields();
 if(el.id==='entry-date'&&el.value>F.today())$('#entry-form').elements.status.value='planned';
 if(el.id==='share-assets'){shareIncludeAssets=el.checked;render();}
 if(el.id==='share-days')shareDays=Number(el.value);
 if(el.id==='backup-file')importBackup(el.files[0]);
});
document.addEventListener('input',event=>{if(event.target.id==='ledger-search'){entryQuery=event.target.value;entryPage=0;$('#ledger-table-region').innerHTML=ledgerTable();}if(event.target.id==='global-search')updateSearch(event.target.value);});
document.addEventListener('submit',async event=>{
 const f=event.target;if(!['entry-form','subscription-form','charge-form','account-form','new-account-form','category-form','settings-form','comment-form','friend-form'].includes(f.id))return;event.preventDefault();if(accountChanged)return toast('현재 계정을 다시 확인한 뒤 이용해 주세요.');const d=Object.fromEntries(new FormData(f));
 try{
  let next=structuredClone(state),message='저장했어요.';
  if(f.id==='entry-form'){
   const old=state.entries.find(e=>e.id===f.dataset.id),kind=d.kind,value=Number(d.amount);
   if(!d.description.trim())return formError('내용을 입력해 주세요.');if(d.status==='posted'&&d.date>F.today())return formError('미래의 거래는 ‘예정’으로 기록해 주세요.');
   const e={id:old?.id||F.uuid(),date:d.date,kind,amount:kind==='valuation'?0:value,description:d.description.trim(),status:d.status,order:old?.order??Date.now(),memo:d.memo.trim()};
   if(d.from)e.from=d.from;if(d.to)e.to=d.to;if(d.categoryId)e.categoryId=d.categoryId;if(kind==='valuation'){e.accountId=d.accountId;e.targetBalance=value;}
   if(old?.subscriptionId&&kind==='expense'){e.subscriptionId=old.subscriptionId;e.scheduledDate=old.scheduledDate;}
   next.entries=old?next.entries.map(v=>v.id===old.id?e:v):[...next.entries,e];message=old?'거래를 수정하고 흐름을 다시 계산했어요.':'새 기록을 재무제표에 반영했어요.';
  }else if(f.id==='subscription-form'){
   const old=state.subscriptions.find(s=>s.id===f.dataset.id),s={id:old?.id||F.uuid(),name:d.name.trim(),amount:Number(d.amount),cadence:d.cadence,anchorDate:d.anchorDate,accountId:d.accountId,categoryId:d.categoryId,remindDays:Number(d.remindDays),active:d.active==='true',color:d.color,memo:d.memo.trim()};
   next.subscriptions=old?next.subscriptions.map(v=>v.id===old.id?s:v):[...next.subscriptions,s];message=old?'구독 정보를 수정했어요.':'새 구독을 추가했어요.';
  }else if(f.id==='charge-form'){
   if(d.actualDate>F.today())return formError('실제로 결제한 날짜를 확인해 주세요.');const old=next.entries.find(e=>e.subscriptionId===f.dataset.id&&e.scheduledDate===f.dataset.date);
   if(old){if(old.status==='posted')return formError('이미 결제를 기록했어요.');old.status='posted';old.date=d.actualDate;}
   else{const e=F.recordSubscription(next,f.dataset.id,f.dataset.date);e.date=d.actualDate;next.entries.push(e);}message='구독 결제를 한 번만 지출로 기록했어요.';
  }else if(f.id==='account-form'){
   const a=next.accounts.find(a=>a.id===f.dataset.id);Object.assign(a,{name:d.name.trim(),group:d.group,openingBalance:Number(d.openingBalance),memo:d.memo.trim()});message='계좌 정보를 저장했어요.';
  }else if(f.id==='new-account-form'){
   const liability=['card','loan'].includes(d.group);next.accounts.push({id:F.uuid(),name:d.name.trim(),type:liability?'liability':'asset',group:d.group,openingBalance:Number(d.openingBalance),memo:d.memo.trim(),color:liability?'orange':d.group==='investment'?'purple':d.group==='savings'?'green':'blue'});message='새 계좌를 추가했어요.';
  }else if(f.id==='category-form'){
   const old=state.categories.find(c=>c.id===f.dataset.id),c={id:old?.id||F.uuid(),name:d.name.trim(),type:d.type,group:d.type==='income'?'variable':d.group,shareGroup:d.shareGroup,color:old?.color||'purple'};
   next.categories=old?next.categories.map(v=>v.id===old.id?c:v):[...next.categories,c];message='분류를 저장했어요.';
  }else if(f.id==='settings-form'){
   next.book.name=d.name.trim();next.book.openingDate=d.openingDate;next.settings.monthlyBudget=Number(d.budget);message='나에게 맞는 설정을 저장했어요.';
  }else if(f.id==='comment-form'){
   const submit=$('button[type="submit"]',f);submit.disabled=true;try{await api('shares/'+encodeURIComponent(shareToken)+'/comments',{method:'POST',body:{nickname:d.nickname.trim(),text:d.text.trim()}});await loadShared();toast('따뜻한 조언을 남겼어요.');}finally{if(submit.isConnected)submit.disabled=false;}return;
  }else if(f.id==='friend-form'){
   const url=new URL(d.url),token=url.searchParams.get('share');if(url.origin!==location.origin||url.pathname!=='/moaflow/'||!token||!/^[A-Za-z0-9_-]{32}$/.test(token))return formError('이 사이트에서 만든 모아흐름 공유 링크를 넣어 주세요.');shareToken=token;history.replaceState(null,'','/moaflow/?share='+token);closeModal();await loadShared();return;
  }
  F.validateState(next);state=next;if(f.id!=='settings-form')closeModal();commit(message);
 }catch(error){formError(error.message||'입력한 내용을 확인해 주세요.');}
});
async function importBackup(file){if(!file)return;if(file.size>2500000)return toast('2.5MB 이하의 전체 백업 JSON을 선택해 주세요.');try{const incoming=F.validateState(JSON.parse(await file.text()));showModal('백업 자료로 복원할까요?',`${incoming.accounts.length}개 계좌 · ${incoming.entries.length}개 기록`,`<p class="subtle">현재 가계부를 선택한 백업으로 교체해요. 현재 기록이 필요하다면 먼저 전체 백업을 저장해 주세요.</p><div class="form-actions"><button class="btn" data-action="export-backup">현재 자료 백업</button><button class="btn" data-action="close-modal">취소</button><button class="btn primary" id="confirm-backup">이 자료로 복원</button></div>`);$('#confirm-backup').addEventListener('click',()=>{state=incoming;syncError='';closeModal();commit('백업 자료를 불러왔어요.');});}catch(error){toast(error.message||'올바른 모아흐름 백업이 아니에요.');}}
document.addEventListener('keydown',event=>{
 if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchModal();return;}
 if((event.key==='Enter'||event.key===' ')&&event.target.matches('.sankey-node,.chart-point,.river-node,.river-expand,.river-hit')){event.preventDefault();handleAction(event.target.dataset.action,event.target.dataset.id,event.target).catch(e=>toast(e.message));return;}
 if(!$('#modal-root').children.length)return;if(event.key==='Escape'){event.preventDefault();closeModal();}
 if(event.key==='Tab'){const nodes=[...$('.modal').querySelectorAll('button:not([disabled]),a[href],input:not([type="hidden"]),select,textarea,[tabindex="0"]')].filter(el=>el.getClientRects().length);if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0]?.focus();}}
});
document.addEventListener('pointerover',event=>{const n=event.target.closest('[data-node]');if(n)document.querySelectorAll('.sankey-link').forEach(p=>{const match=p.dataset.linkFrom===n.dataset.node||p.dataset.linkTo===n.dataset.node;p.classList.toggle('highlight',match);p.classList.toggle('dim',!match);});});
document.addEventListener('pointerout',event=>{if(event.target.closest('[data-node]'))document.querySelectorAll('.sankey-link').forEach(p=>p.classList.remove('highlight','dim'));});
window.addEventListener('hashchange',()=>{if(location.hash==='#main-content')return;if(shareToken){shareToken=null;shared=null;history.replaceState(null,'','/moaflow/'+location.hash);}closeModal();entryPage=0;render();window.scrollTo({top:0,behavior:'instant'});if(page==='sharing')loadShares();});
function inspectRiver(event){const el=event.target.closest?.('[data-river-info]');if(!el)return;const key=el.dataset.riverNode||el.closest('[data-river-route]')?.dataset.riverRoute;highlightRiver(document,key);const info=$('#river-inspector');if(info)info.textContent=el.dataset.riverInfo;}
document.addEventListener('pointerover',inspectRiver);document.addEventListener('focusin',inspectRiver);
for(const eventName of ['pointerout','focusout'])document.addEventListener(eventName,event=>{if(event.target.closest?.('[data-river-info]')){highlightRiver(document,null);const info=$('#river-inspector');if(info)info.textContent='입자가 움직이는 길을 따라가 보세요. 계좌와 연결선을 누르면 기록을 수정할 수 있어요.';}});
document.addEventListener('visibilitychange',()=>syncRiverMotion(document,motionPaused));
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{if(page==='dashboard')render();});
window.addEventListener('online',()=>{if(dirty){syncError='';saveCloud();}});
window.addEventListener('beforeunload',event=>{if(!accountChanged&&(saving||dirty)){event.preventDefault();event.returnValue='';}});
window.addEventListener('storage',event=>{if(event.key===storageKey()&&event.newValue){if(dirty){syncError='다른 탭에서 수정한 내용이 있어요. 백업 후 최신 자료를 확인해 주세요.';render();}else{try{const cached=JSON.parse(event.newValue);state=F.validateState(cached.state);revision=cached.revision||0;render();}catch{}}}});
async function init(){
 try{session=await api('session');}catch{session={authenticated:false,signInUrl:'/signin-with-chatgpt?return_to=%2Fmoaflow%2F'};}
 if(ledgerBrand.embedded){session.signInUrl=ledgerBrand.signInUrl;session.signOutUrl=ledgerBrand.signOutUrl;}
 if(session.authenticated){
  const cached=read(cloudKey());
  try{const remote=await api('state');revision=remote.revision;
   if(cached?.dirty&&cached.state&&!cached.state.sample){state=F.validateState(cached.state);dirty=true;if(cached.revision!==remote.revision)syncError='이 기기에 아직 전송하지 못한 기록이 있어요. 백업 후 최신 자료와 비교해 주세요.';}
   else state=remote.state?F.validateState(remote.state):F.blankState();
   saveStatus=dirty?'기기 저장 · 동기화 필요':remote.state?'계정에 저장됨':'내 가계부를 시작해요';
  }catch{try{state=cached?.state?F.validateState(cached.state):F.blankState();revision=cached?.revision||0;dirty=!!cached?.dirty;}catch{state=F.blankState();}syncError='계정 자료를 불러오지 못했어요. 연결을 확인하고 최신 자료를 다시 열어 주세요.';saveStatus='연결 확인 필요';}
  memoryLinks=read('moaflow:share-links:'+session.user.key)||{};
 }else{const stored=inspectBrowserLedger();if(stored.status==='valid')state=stored.record.state;else{const demo=read(DEMO_KEY);try{state=demo?.state?F.validateState(demo.state):F.demoState();}catch{state=F.demoState();}}saveStatus=state.sample?'예시로 체험 중':'이 브라우저에 저장';}
 render();if(shareToken)await loadShared();else if(page==='sharing')loadShares();if(dirty&&!syncError)saveCloud();
 if('serviceWorker'in navigator&&isSecureContext)navigator.serviceWorker.register('/moaflow/sw.js',{scope:'/moaflow/'}).catch(()=>{});
 checkNotifications();setInterval(checkNotifications,60000);
}
init();
